import ast,subprocess,sys,collections
files=subprocess.check_output(['git','ls-files','*.py']).decode().split()
classes=collections.defaultdict(list)
for f in files:
    try: t=ast.parse(open(f,encoding='utf-8').read())
    except Exception as e: print("ERR",f,e,file=sys.stderr); continue
    for n in ast.walk(t):
        if isinstance(n,ast.ClassDef):
            bases=[]
            for b in n.bases:
                if isinstance(b,ast.Name): bases.append(b.id)
                elif isinstance(b,ast.Attribute): bases.append(b.attr)
                elif isinstance(b,ast.Call) and isinstance(b.func,(ast.Name,ast.Attribute)): bases.append(getattr(b.func,'id',getattr(b.func,'attr',None)))
            classes[n.name].append((f,bases,n.lineno))
seen={'StockController'};changed=True
while changed:
    changed=False
    for name,defs in classes.items():
        for f,b,l in defs:
            if name not in seen and any(x in seen for x in b): seen.add(name);changed=True
for name,defs in sorted(classes.items()):
    for f,b,l in defs:
        if name in seen and name!='StockController' or any(x in seen for x in b):
            print(f"{name}\t{f}:{l}\t{b}")
print("StockController defs:",classes['StockController'])
